package com.arqly.backend.controller;
import com.arqly.backend.dto.*;import com.arqly.backend.dto.NotificationDtos.*;import com.arqly.backend.entity.*;import com.arqly.backend.security.AuthenticatedUser;import com.arqly.backend.service.NotificationService;import java.util.*;import org.springframework.data.domain.*;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/notifications") public class NotificationController {private final NotificationService service;public NotificationController(NotificationService service){this.service=service;}@GetMapping public ApiResponse<Page<NotificationResponse>> list(@AuthenticationPrincipal AuthenticatedUser u,@RequestParam(required=false) NotificationStatus status,@RequestParam(required=false) NotificationCategory category,@RequestParam(required=false) NotificationPriority priority,Pageable pageable){return ApiResponse.ok(service.list(u.getTenantId(),u.getId(),status,category,priority,pageable));}@GetMapping("/unread-count") public ApiResponse<Long> unread(@AuthenticationPrincipal AuthenticatedUser u){return ApiResponse.ok(service.unreadCount(u.getTenantId(),u.getId()));}@PostMapping("/{id}/read") public ApiResponse<NotificationResponse> read(@AuthenticationPrincipal AuthenticatedUser u,@PathVariable UUID id){return ApiResponse.ok(service.read(u.getTenantId(),u.getId(),id,true));}@PostMapping("/{id}/unread") public ApiResponse<NotificationResponse> unread(@AuthenticationPrincipal AuthenticatedUser u,@PathVariable UUID id){return ApiResponse.ok(service.read(u.getTenantId(),u.getId(),id,false));}@PostMapping("/{id}/archive") public ApiResponse<Void> archive(@AuthenticationPrincipal AuthenticatedUser u,@PathVariable UUID id){service.archive(u.getTenantId(),u.getId(),id);return ApiResponse.message("Notificação arquivada.");}@PostMapping("/read-all") public ApiResponse<Void> readAll(@AuthenticationPrincipal AuthenticatedUser u){service.readAll(u.getTenantId(),u.getId());return ApiResponse.message("Notificações marcadas como lidas.");}@GetMapping("/preferences") public ApiResponse<List<NotificationPreferenceResponse>> preferences(@AuthenticationPrincipal AuthenticatedUser u){return ApiResponse.ok(service.preferences(u.getTenantId(),u.getId()));}@PutMapping("/preferences") public ApiResponse<List<NotificationPreferenceResponse>> preferences(@AuthenticationPrincipal AuthenticatedUser u,@RequestBody List<NotificationPreferenceRequest> requests){return ApiResponse.ok(service.updatePreferences(u.getTenantId(),u.getId(),requests));}}
